//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 


    auto linear = +[](Scalar& output, Scalar input, Scalar alpha) noexcept {
        output = input;
    };

    auto leakyrelu = +[](Scalar& output, Scalar input, Scalar alpha) noexcept {
        output = input > 0 ? input : alpha * input;
    };


//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 

    
    // model input and flattened
    constexpr int flat_size = 9216; 
    std::array<Scalar, flat_size> model_input;

    // normalize input
    for (int i = 0; i < 9216; i++) { model_input[i] = (initial_input[i] - input_min_mean[i]) / (input_norm_std[i]); } 

    if (model_input.size() != 9216) { throw std::invalid_argument("Invalid input size. Expected size: 9216"); }

    // Dense, layer 1
    static std::array<Scalar, 2> layer_1_output;
    Dense_MLP_1_BE_second<Scalar, 2>(
        layer_1_output.data(), model_input.data(),
        weights_1.data(), biases_1.data(),
        9216, linear, 0.0);

    // BatchNormalization, layer 2
    static std::array<Scalar, 2> layer_2_output;
    BatchNormalization_MLP_1_BE_second<Scalar, 2>(
        layer_2_output.data(), layer_1_output.data(),
        gamma_2.data(), beta_2.data(),
        mean_2.data(), variance_2.data(),
        epsilon_2);

    // Activation, layer 3
    static std::array<Scalar, 2> layer_3_output;
    for (int i = 0; i < 2; ++i) {
        leakyrelu(layer_3_output[i], layer_2_output[i], 0.0005);
    }

    // Dense, layer 4
    static std::array<Scalar, 2> layer_4_output;
    Dense_MLP_1_BE_second<Scalar, 2>(
        layer_4_output.data(), layer_3_output.data(),
        weights_4.data(), biases_4.data(),
        2, linear, 0.0);

    // Activation, layer 5
    static std::array<Scalar, 2> layer_5_output;
    for (int i = 0; i < 2; ++i) {
        leakyrelu(layer_5_output[i], layer_4_output[i], 0.0005);
    }

    // Dense, layer 6
    static std::array<Scalar, 9216> layer_6_output;
    Dense_MLP_1_BE_second<Scalar, 9216>(
        layer_6_output.data(), layer_5_output.data(),
        weights_6.data(), biases_6.data(),
        2, linear, 0.0);


//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 


    static std::array<Scalar, 9216> model_output;

    for (int i = 0; i < 9216; i++) { model_output[i] = (layer_6_output[i] * output_norm_std[i]) + output_min_mean[i]; }

    return model_output;

